import { Data, Effect } from "effect"

export interface StockReservation {
  readonly id: string
  readonly sku: string
  readonly quantity: number
  readonly expiresAt: Date
}

export interface ReserveStockRequest {
  readonly requestId: string
  readonly sku: string
  readonly quantity: number
}

export class InventoryReserveError extends Data.TaggedError("InventoryReserveError")<{
  readonly requestId: string
  readonly cause: unknown
}> {}

export class InventoryReleaseError extends Data.TaggedError("InventoryReleaseError")<{
  readonly requestId: string
  readonly cause: unknown
}> {}

export interface InventoryReservations {
  readonly reserve: (
    request: ReserveStockRequest
  ) => Effect.Effect<StockReservation, InventoryReserveError>

  readonly release: (
    requestId: string,
    reservationId: string
  ) => Effect.Effect<void, InventoryReleaseError>
}
